using OmniRemote.Domain.Commands;

namespace OmniRemote.Domain.Devices;

/// <summary>Where a piece of state came from. UI must label Simulated data clearly.</summary>
public enum StateOrigin
{
    Unknown,
    /// <summary>Inferred from an acknowledged or unconfirmed command; not verified by device feedback.</summary>
    Assumed,
    /// <summary>Reported by the real device or hub.</summary>
    Reported,
    /// <summary>Generated by the simulation engine. Not a real measurement.</summary>
    Simulated,
}

public sealed record DeviceState
{
    public static DeviceState Empty { get; } = new();

    public IReadOnlyDictionary<string, string> Values { get; init; } = new Dictionary<string, string>();
    public StateOrigin Origin { get; init; } = StateOrigin.Unknown;
    public DateTimeOffset? UpdatedAt { get; init; }

    public string? Get(string key) => Values.TryGetValue(key, out var v) ? v : null;
}

public enum ConnectionState { Disconnected, Connecting, Connected, Unavailable }

/// <summary>Immutable activity history entry.</summary>
public sealed record ActivityEntry
{
    public required Guid Id { get; init; }
    public required Guid RequestId { get; init; }
    public required Guid DeviceId { get; init; }
    public required string DeviceName { get; init; }
    public required string CommandName { get; init; }
    public string Parameters { get; init; } = "";
    public required CommandStatus Status { get; init; }
    public CommandErrorCode ErrorCode { get; init; }
    public required DateTimeOffset Timestamp { get; init; }
    public bool Simulated { get; init; }
    public string? Message { get; init; }

    public bool HasParameters => !string.IsNullOrEmpty(Parameters);
    public string FormattedTime => Timestamp.LocalDateTime.ToString("HH:mm:ss");
}
